<?php include 'conexao.php';$id=(int)($_GET['id']??0);$stmt=$conn->prepare('SELECT * FROM produtos WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();$p=$stmt->get_result()->fetch_assoc();if(!$p){header('Location:index.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$nome=trim($_POST['nome']??'');$desc=trim($_POST['descricao']??'');if($nome!==''){$stmt=$conn->prepare('UPDATE produtos SET nome=?,descricao=? WHERE id=?');$stmt->bind_param('ssi',$nome,$desc,$id);$stmt->execute();header('Location:index.php');exit;}}?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Editar produto • CRUD</title><link rel="stylesheet" href="style.css"></head><body><header class="navbar"><div class="container nav-inner"><a class="brand" href="index.php">CRUD<span>Produtos</span></a><div class="nav-badge">Edição #<?=$id?></div></div></header><main class="main"><div class="container"><div class="form-card card"><div class="eyebrow">Atualização</div><h1 class="title">Editar produto</h1><p class="subtitle" style="margin-bottom:28px">Altere as informações e salve as mudanças.</p><form method="post"><div class="form-group"><label class="label">Nome do produto</label><input class="input" name="nome" required maxlength="100" value="<?=htmlspecialchars($p['nome'])?>"></div><div class="form-group"><label class="label">Descrição</label><textarea class="textarea" name="descricao"><?=htmlspecialchars($p['descricao']??'')?></textarea></div><div class="form-actions"><a class="btn btn-secondary" href="index.php">Cancelar</a><button class="btn btn-primary" type="submit">Salvar alterações</button></div></form></div></div></main></body></html>